// The app's own typefaces, carried inside it.
//
// raffy, 2026-09-01: "i want the font of the app is same like font for phu quoc
// app . especially the title."
//
// It already was, on paper. The template asks for `url(fonts/outfit.woff2)` —
// a RELATIVE path, which works perfectly in the Phu Quoc app because the file
// sits next to the HTML. A generated trip is one standalone file: served from
// Vercel, downloaded to a phone, opened from a share sheet. There is no
// fonts/ directory beside it anywhere along that path, so both faces failed
// silently and every heading fell back to the system sans. Nothing errored;
// it just quietly stopped being the same app.
//
// Base64 rather than a CDN, for the same reason the app caches everything
// else: it has to work on a phone with no signal at a counter at 6am, and a
// Google Fonts request is one more thing that can be blocked, slow or gone.
// 37KB of woff2 becomes 50KB of text, which is a third of what one photo costs.

export const OUTFIT = '';
export const JAKARTA = '';

export const FACE = (family, b64, weights) =>
  "@font-face{font-family:'" + family + "';font-weight:" + weights
  + ";font-style:normal;font-display:swap;"
  + "src:url(data:font/woff2;base64," + b64 + ") format('woff2')}";
